import Foundation
import Darwin
import PetCore

/// Owns one opencode server connection: the shared v2 service when its descriptor is
/// present, otherwise a spawned `opencode serve` child. Only ThreadState snapshots cross
/// to the UI.
///
/// opencode 2.x moved the HTTP API to `/api/*`, requires Basic auth with the password
/// generated by the server (persisted in `service.json`), wraps list responses in
/// `{ "data": ... }`, and exposes live work through `/api/session/active`. The SSE
/// envelope now puts event fields under `data` instead of `properties`. The 1.x
/// `/session`, `/session/status`, and `/event` routes are still detected as a fallback.
final class OpenCodeWatcher {
    private enum API { case unknown, v2, v1 }
    private let queue = DispatchQueue(label: "codex-harem.opencode", qos: .utility)
    private let executable: String
    private let services: [URL]
    private var process: Process?
    private var port = 0
    private var password = ""
    private var attachedToService = false
    private var api: API = .unknown
    private var timer: DispatchSourceTimer?
    private var retryAt = Date.distantPast
    private var missedPolls = 0
    private var sessions: [String: ThreadState] = [:]
    private var waiting = Set<String>()
    private var previous: [String: PetStatus] = [:]
    private var sseSession: URLSession?
    private var sseTask: URLSessionDataTask?
    private var sseBuffer = Data()
    private var pollSession: URLSession?
    private let activity: OpenCodeActivity?
    private var diagnostic = "opencode · starting server…"
    var onUpdate: (([ThreadState], String) -> Void)?
    init(executable: String, database: URL? = nil, services: [URL] = []) {
        self.executable = executable
        self.services = services
        activity = database.map(OpenCodeActivity.init(database:))
    }
    func start() {
        let timer = DispatchSource.makeTimerSource(queue: queue)
        timer.schedule(deadline: .now(), repeating: 1)
        timer.setEventHandler { [weak self] in self?.tick() }
        self.timer = timer; timer.resume()
    }
    func stop() { queue.sync { timer?.cancel(); timer = nil; disconnect(retry: false) } }
    private func tick() {
        if port == 0 {
            if Date() >= retryAt { connect() }
            return
        }
        guard poll() else {
            // A spawned server needs a moment to accept connections; a shared service
            // may have shut down. Give up after three misses and retry cleanly.
            missedPolls += 1
            if missedPolls >= 3 { disconnect(retry: true) }
            return
        }
        missedPolls = 0
        if sseTask == nil { connectSSE() }
        emit()
    }
    private func connect() {
        if adoptService() { return }
        spawnServer()
    }
    /// Connects to opencode 2.x's long-lived `opencode serve --service` when it is
    /// running. That process owns TUI sessions, so its `/api/session/active` map is the
    /// only live status source for them.
    private func adoptService() -> Bool {
        for file in services {
            guard let data = try? Data(contentsOf: file),
                  let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                  let endpoint = Self.serviceEndpoint(object),
                  healthCheck(port: endpoint.port, password: endpoint.password) else { continue }
            port = endpoint.port; password = endpoint.password; attachedToService = true
            api = .unknown; missedPolls = 0
            diagnostic = "opencode · shared service on 127.0.0.1:\(port)"
            makeSessions()
            emit()
            return true
        }
        return false
    }
    private func spawnServer() {
        guard FileManager.default.isExecutableFile(atPath: executable) else {
            diagnostic = "opencode · CLI not found; Codex and Claude Code still work"
            retryAt = Date().addingTimeInterval(30)
            emit()
            return
        }
        guard let chosen = Self.freePort() else {
            diagnostic = "opencode · no free local port"; retryAt = Date().addingTimeInterval(10); emit(); return
        }
        let task = Process(), stdout = Pipe(), stderr = Pipe()
        var environment = ProcessInfo.processInfo.environment
        // opencode 2.x generates a random password when this is unset and only prints it
        // to stdout. Supplying our own keeps the spawned server reachable.
        let secret = environment["OPENCODE_SERVER_PASSWORD"] ?? Self.randomPassword()
        environment["OPENCODE_SERVER_PASSWORD"] = secret
        task.environment = environment
        task.executableURL = URL(fileURLWithPath: executable)
        task.arguments = ["serve", "--port", String(chosen), "--hostname", "127.0.0.1"]
        task.standardOutput = stdout; task.standardError = stderr
        stdout.fileHandleForReading.readabilityHandler = { handle in if handle.availableData.isEmpty { handle.readabilityHandler = nil } }
        stderr.fileHandleForReading.readabilityHandler = { handle in if handle.availableData.isEmpty { handle.readabilityHandler = nil } }
        task.terminationHandler = { [weak self] finished in
            self?.queue.async { [weak self] in
                guard let self, self.process === finished else { return }
                self.diagnostic = "opencode · server unavailable, retrying"
                self.disconnect(retry: true)
            }
        }
        do { try task.run() } catch {
            diagnostic = "opencode · cannot launch CLI"; retryAt = Date().addingTimeInterval(10); emit(); return
        }
        process = task; port = chosen; password = secret; attachedToService = false
        api = .unknown; missedPolls = 0
        diagnostic = "opencode · starting server…"
        makeSessions()
    }
    private func makeSessions() {
        let pollConfig = URLSessionConfiguration.ephemeral
        pollConfig.connectionProxyDictionary = [:]
        pollConfig.timeoutIntervalForRequest = 3
        pollSession = URLSession(configuration: pollConfig)
        let sseConfig = URLSessionConfiguration.ephemeral
        sseConfig.connectionProxyDictionary = [:]
        sseConfig.timeoutIntervalForRequest = 86_400
        sseConfig.timeoutIntervalForResource = 86_400
        let handler = SSEHandler(queue: queue, onChunk: { [weak self] data in
            self?.receive(data)
        }, onFinish: { [weak self] in
            self?.sseTask = nil
        })
        sseSession = URLSession(configuration: sseConfig, delegate: handler, delegateQueue: nil)
    }
    private func disconnect(retry: Bool) {
        if !attachedToService { process?.terminate() }
        process = nil
        sseTask?.cancel(); sseTask = nil
        sseSession?.invalidateAndCancel(); sseSession = nil
        pollSession?.finishTasksAndInvalidate(); pollSession = nil
        sessions.removeAll(); waiting.removeAll(); previous.removeAll(); sseBuffer.removeAll()
        port = 0; password = ""; attachedToService = false; api = .unknown; missedPolls = 0
        if retry { retryAt = Date().addingTimeInterval(10) }
    }
    private func request(_ path: String) -> URLRequest {
        let request = NSMutableURLRequest(url: URL(string: "http://127.0.0.1:\(port)\(path)")!)
        if !password.isEmpty {
            request.setValue("Basic \(Self.credentials(password))", forHTTPHeaderField: "Authorization")
        }
        return request as URLRequest
    }
    private func getJSON(_ path: String) -> Any? {
        guard let pollSession else { return nil }
        var payload: Any?
        let semaphore = DispatchSemaphore(value: 0)
        var request = request(path); request.timeoutInterval = 3
        pollSession.dataTask(with: request) { data, response, _ in
            if let http = response as? HTTPURLResponse, http.statusCode == 200, let data,
               let object = try? JSONSerialization.jsonObject(with: data) { payload = object }
            semaphore.signal()
        }.resume()
        _ = semaphore.wait(timeout: .now() + 4)
        return payload
    }
    /// Returns false when neither API version answered, so a starting server is retried.
    private func poll() -> Bool {
        var list: [[String: Any]]?
        if api != .v1, let payload = getJSON("/api/session"), let rows = Self.sessionList(payload) {
            api = .v2; list = rows
        } else if api != .v2, let rows = getJSON("/session") as? [[String: Any]] {
            api = .v1; list = rows
        }
        guard let list else { return false }
        diagnostic = attachedToService
            ? "opencode · shared service on 127.0.0.1:\(port)"
            : "opencode · server on 127.0.0.1:\(port)"
        let statusPath = api == .v2 ? "/api/session/active" : "/session/status"
        let statusMap = Self.statusMap(getJSON(statusPath))
        let liveTurns = activity?.poll(now: Date()) ?? [:]
        var result: [String: ThreadState] = [:]
        for record in list {
            guard let ses = record["id"] as? String else { continue }
            let id = "opencode:" + ses
            if let title = record["title"] as? String, !title.isEmpty { sessions[id]?.name = title }
            var stamp = sessions[id]?.updatedAt ?? Date()
            if let time = record["time"] as? [String: Any], let updated = (time["updated"] as? NSNumber)?.doubleValue {
                stamp = Date(timeIntervalSince1970: updated / 1000)
            }
            let mapped = (statusMap[ses] as? [String: Any]).flatMap { OpenCodeReducer.sessionStatus($0) } ?? .idle
            // Shared storage recovers busy state for sessions owned by other server
            // processes. Attached to the shared service, its active map and SSE stream are
            // authoritative: recent rows can hide behind exclusive WAL locking there, so
            // stale storage must not override a finished turn.
            let active: PetStatus
            if attachedToService {
                active = OpenCodeReducer.transition(from: previous[id] ?? .idle, to: mapped)
            } else if mapped == .thinking {
                active = (liveTurns[ses] == .working) ? .working : .thinking
            } else {
                active = liveTurns[ses] ?? OpenCodeReducer.transition(from: previous[id] ?? .idle, to: mapped)
            }
            let effective = waiting.contains(ses) ? .waiting : active
            previous[id] = effective
            result[id] = ThreadState(id: id, name: sessions[id]?.name ?? "opencode · \(ses.prefix(12))", status: effective, updatedAt: stamp, harness: .opencode)
        }
        sessions = result
        return true
    }
    private func connectSSE() {
        guard let sseSession else { return }
        let path = api == .v1 ? "/event" : "/api/event"
        sseTask = sseSession.dataTask(with: request(path))
        sseTask?.resume()
    }
    private func receive(_ chunk: Data) {
        sseBuffer.append(chunk)
        while let end = sseBuffer.firstIndex(of: 10) {
            let line = sseBuffer[..<end]; sseBuffer.removeSubrange(...end)
            guard let text = String(data: line, encoding: .utf8) else { continue }
            guard text.hasPrefix("data:"), let object = (try? JSONSerialization.jsonObject(with: Data(text.dropFirst(5).utf8))) as? [String: Any] else { continue }
            guard let (ses, status) = OpenCodeReducer.event(object) else { continue }
            let id = "opencode:" + ses
            switch status {
            case .waiting: waiting.insert(ses)
            default: waiting.remove(ses)
            }
            var state = sessions[id] ?? ThreadState(id: id, name: "opencode · \(ses.prefix(12))", status: .idle, updatedAt: Date(), harness: .opencode)
            let effective = status == .waiting ? .waiting : OpenCodeReducer.transition(from: previous[id] ?? .idle, to: status)
            previous[id] = effective
            state.status = effective; state.updatedAt = Date()
            sessions[id] = state
        }
        if sseBuffer.count > 8_388_608 { sseBuffer.removeAll() }
        emit()
    }
    private func emit() {
        let states = sessions.values.sorted { $0.updatedAt > $1.updatedAt }
        let description = diagnostic
        DispatchQueue.main.async { [weak self] in self?.onUpdate?(states, description) }
    }
    private func healthCheck(port: Int, password: String) -> Bool {
        guard let url = URL(string: "http://127.0.0.1:\(port)/api/session") else { return false }
        var request = URLRequest(url: url)
        request.timeoutInterval = 1.5
        if !password.isEmpty { request.setValue("Basic \(Self.credentials(password))", forHTTPHeaderField: "Authorization") }
        let config = URLSessionConfiguration.ephemeral
        config.connectionProxyDictionary = [:]
        config.timeoutIntervalForRequest = 1.5
        let session = URLSession(configuration: config)
        let semaphore = DispatchSemaphore(value: 0)
        var ok = false
        session.dataTask(with: request) { _, response, _ in
            ok = (response as? HTTPURLResponse)?.statusCode == 200
            semaphore.signal()
        }.resume()
        _ = semaphore.wait(timeout: .now() + 2)
        session.finishTasksAndInvalidate()
        return ok
    }
    private static func serviceEndpoint(_ object: [String: Any]) -> (port: Int, password: String)? {
        let password = object["password"] as? String ?? ""
        if let text = object["url"] as? String, let url = URL(string: text), let port = url.port {
            return (port, password)
        }
        if let number = object["port"] as? NSNumber { return (number.intValue, password) }
        if let text = object["port"] as? String, let port = Int(text) { return (port, password) }
        return nil
    }
    private static func credentials(_ password: String) -> String {
        Data("opencode:\(password)".utf8).base64EncodedString()
    }
    private static func randomPassword() -> String {
        UUID().uuidString.replacingOccurrences(of: "-", with: "")
    }
    private static func sessionList(_ payload: Any?) -> [[String: Any]]? {
        if let rows = payload as? [[String: Any]] { return rows }
        if let dict = payload as? [String: Any], let rows = dict["data"] as? [[String: Any]] { return rows }
        return nil
    }
    private static func statusMap(_ payload: Any?) -> [String: Any] {
        guard let dict = payload as? [String: Any] else { return [:] }
        if let data = dict["data"] as? [String: Any] { return data }
        return dict
    }
    private static func freePort() -> Int? {
        let fd = socket(AF_INET, SOCK_STREAM, 0)
        guard fd >= 0 else { return nil }
        defer { close(fd) }
        var yes: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, socklen_t(MemoryLayout<Int32>.size))
        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = 0
        addr.sin_addr = in_addr(s_addr: INADDR_ANY)
        let bound = withUnsafePointer(to: &addr) { pointer in
            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
        guard bound == 0, listen(fd, 1) == 0 else { return nil }
        var resolved = sockaddr_in(), length = socklen_t(MemoryLayout<sockaddr_in>.size)
        let named = withUnsafeMutablePointer(to: &resolved) { pointer in
            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                getsockname(fd, $0, &length)
            }
        }
        guard named == 0 else { return nil }
        return Int(UInt16(bigEndian: resolved.sin_port))
    }
}

/// URLSession delegate that forwards SSE stream chunks to the watcher queue.
private final class SSEHandler: NSObject, URLSessionDataDelegate {
    private let queue: DispatchQueue
    private let onChunk: (Data) -> Void
    private let onFinish: () -> Void
    init(queue: DispatchQueue, onChunk: @escaping (Data) -> Void, onFinish: @escaping () -> Void) {
        self.queue = queue; self.onChunk = onChunk; self.onFinish = onFinish
    }
    func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive data: Data) {
        onChunk(data)
    }
    func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
        queue.asyncAfter(deadline: .now() + 2, execute: onFinish)
    }
}
